import math

def kl_divergence(p: list, q: list) -> float:
    """KL(p || q) = sum_i p_i * log(p_i / q_i), skipping p_i == 0."""
    total = 0.0
    for pi, qi in zip(p, q):
        if pi > 0:
            total += pi * math.log(pi / qi)
    return round(total, 4)

print(kl_divergence([0.4942, 0.2998, 0.206], [0.4192, 0.3265, 0.2543]))
